const output = [];

for (const item of $input.all()) {
  const itemData = item.json.output;

  const n_question = itemData.question;
  const n_subclaim = itemData.subclaim;
  const n_results = [];

  for (const result of itemData.results) {

    if (result.is_relevant) {
      n_results.push(result);
    }

  }


  output.push({
    subclaim: n_subclaim,
    question: n_question,
    results: n_results
  });
}

return output

