parameters.jsCode:
// Récupérer tous les items
const items = $input.all();

// Créer un objet pour grouper par searchParameters.q
const grouped = {};

// Parcourir tous les items
items.forEach(item => {
  const question = item.json.question;
  const news = item.json.news;
  const subclaim = item.json.subclaim;

  // Si la query n'existe pas encore, l'initialiser
  if (!grouped[question]) {
    grouped[question] = {
      'question': question,
      'subclaim': subclaim,
      'results': []
    };
  }

  // Ajouter les news aux résultats
  if (news) {
    grouped[question].results.push(news);
  }
});

// Convertir l'objet en tableau
const output = Object.values(grouped);

// Retourner le résultat
return output.map(item => ({ json: item }));

// ========================================
// CODE N8N - AGRÉGATION PAR SUBCLAIM ET QUESTION
// ========================================
// À copier-coller dans un nœud Code de N8N

// Récupération des données d'entrée
const inputData = $input.all();

// Structure pour stocker les données agrégées
const aggregated = {};

// Parcourir toutes les données
for (const item of inputData) {
  const json = item.json;

  const subclaim = json.subclaim;
  const question = json.question;
  const text = json.text;
  const evidenceExtraction = json.evidence_extration; // Note: typo dans les données originales
  const sourceLink = json.source_link;
  const sourceName = json.source_name;

  // Initialiser le subclaim s'il n'existe pas
  if (!aggregated[subclaim]) {
    aggregated[subclaim] = {
      subclaim: subclaim,
      questions: {}
    };
  }

  // Initialiser la question si elle n'existe pas
  if (!aggregated[subclaim].questions[question]) {
    aggregated[subclaim].questions[question] = {
      question: question,
      sources: []
    };
  }

  // Ajouter la source pour cette question
  aggregated[subclaim].questions[question].sources.push({
    //text: text,
    evidence_extraction: evidenceExtraction,
    source_link: sourceLink,
    source_name: sourceName,
  });
}

// Convertir en format de sortie pour N8N
const subclaims = [];

for (const subclaimKey in aggregated) {
  const subclaimData = aggregated[subclaimKey];

  // Convertir les questions en tableau
  const questionsArray = [];
  for (const questionKey in subclaimData.questions) {
    questionsArray.push(subclaimData.questions[questionKey]);
  }

  // Calculer les statistiques
  const totalSources = questionsArray.reduce((sum, q) => sum + q.sources.length, 0);

  subclaims.push({
    json: {
      subclaim: subclaimData.subclaim,
      question_count: questionsArray.length,
      total_sources: totalSources,
      questions: questionsArray
    }
  });
}

return {
  claim: "",
  subclaims: subclaims
};

