{
  "title": "Claim Verification Result",
  "type": "object",
  "properties": {
    "claim": {
      "type": "string",
      "description": "The original claim being verified."
    },
    "final_decision": {
      "type": "string",
      "enum": ["real", "fake"],
      "description": "Final verdict on whether the claim is real or fake."
    },
    "credibility_score": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Overall credibility score of the claim (0–100)."
    },
    "final_justification": {
      "type": "string",
      "description": "Clear explanation of why the claim is real or fake based on the overall evidence."
    },
    "sources_for_investigation": {
      "type": "array",
      "description": "List of source URLs used for investigating the claim.",
      "items": {
        "type": "string",
        "format": "uri",
        "description": "Source URL"
      }
    },
    "subclaim_results": {
      "type": "array",
      "description": "List of subclaims with their verification results.",
      "items": {
        "type": "object",
        "properties": {
          "subclaim": {
            "type": "string",
            "description": "The subclaim being evaluated."
          },
          "classification": {
            "type": "string",
            "enum": ["supported", "not_supported"],
            "description": "Whether the subclaim is supported or not supported by evidence."
          },
          "justification": {
            "type": "string",
            "description": "Short explanation referencing key evidence for the classification."
          }
        },
        "required": ["subclaim", "classification", "justification"]
      }
    }
  },
  "required": ["claim", "final_decision", "credibility_score", "final_justification", "subclaim_results"]
}

